nodes.statement:
Suppose that for every $i\in[N]$ there exists $\mathsf{T}^i\in L^2(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$ such that
\begin{equation} 
    \mathsf{T}^i_\#\mu_0^i=\mu_1^i.
\end{equation}
Consider the flow map $\Phi_1:\mathscr{P}(\mathbb{S}^{d-1})\to\mathscr{P}(\mathbb{S}^{d-1})$ (respectively $\Phi_3$) given by 3.1 with data $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$ (respectively $\mu_1^i\in\mathscr{P}(\mathbb{S}^{d-1})$) for $i\in[N]$. 
Then, there exists a Lipschitz-continuous and invertible map $\Psi:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ such that
\begin{equation} 
\Psi\big|_{\mathrm{supp}\left(\Phi_1(\mu_0^i)\right)}=\Psi^i
\end{equation}
for any $i\in[N]$, where $\Psi^i:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ is another Lipschitz-continuous and invertible map that satisfies
\begin{equation*}
\left(\Psi^i\circ \mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i= \left(\Psi\circ \mathsf{T}^i_{\Phi_1}\right)_\#\mu_0^i=\left(\mathsf{T}^i_{\Phi_3}\right)_\#\mu_1^i=\Phi_3(\mu_1^i)
\end{equation*}
for some Lipschitz-continuous and invertible maps $\mathsf{T}_{\Phi_1}^i, \mathsf{T}_{\Phi_3}^i:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$.

Suppose $\mu\in \mathscr{P}(\mathbb{S}^{d-1})$ and $\mathsf{T}^1,\mathsf{T}^2:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ measurable, with $\mathsf{T}^1$ bijective. Then
\begin{equation} 
\mathsf{W}_2\left(\mathsf{T}^1_\#\mu,\mathsf{T}^2_\#\mu\right)\lesssim\left\|\mathsf{T}^1-\mathsf{T}^2\right\|_{L^2(\mu)}.
\end{equation}

Suppose $\varepsilon>0$ and $\mu\in \mathscr{P}(\mathbb{S}^{d-1})$. 
For every $\Psi\in L^2(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$, there exists a Lipschitz-continuous and invertible map $\Psi_\varepsilon:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the solution map of (C.20), namely 
$$\Phi^T_{\theta_\varepsilon}(\mu)=(\Psi_\varepsilon)_\#\mu$$ for some piecewise constant $\theta_\varepsilon\in L^\infty((0,T);\Uptheta)$ with finitely many switches, such that
\begin{equation*}
\left\|\Psi-\Psi_\varepsilon\right\|_{L^2(\mu)}\leqslant\varepsilon.
\end{equation*}

Suppose $d\geqslant3$. Consider data (1.5) such that
\begin{enumerate}
    \item There exist $w_0,w_1\in\mathbb{S}^{d-1}$ such that 
    \begin{equation} 
        w_0\notin\bigcup_{i\in[N]} \mathrm{supp}(\mu_0^i) \quad \text{ and } \quad w_1\notin\bigcup_{i\in[N]}\mathrm{supp}(\mu_1^i). 
    \end{equation}  
    \item For any $i\in[N]$, there exists $\mathsf{T}^i\in L^2(\mathbb{S}^{d-1};\mathbb{S}^{d-1})$ such that $\mathsf{T}^i_{\#}\mu_0^i=\mu_1^i$.
\end{enumerate}
Then for any $T>0$ and $\varepsilon>0$, there exists $\theta\in L^\infty((0,T);\Uptheta)$ such that for any $i\in[N]$, the unique solution $\mu^i\in\mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to (1.4) with data $\mu_0^i$ and parameters $\theta$ satisfies
    \begin{equation*}
        \mathsf{W}_2\left(\mu^i(T),\mu_1^i\right)\leqslant\varepsilon.
    \end{equation*}
    Moreover, $\theta$ can be chosen piecewise constant.

Suppose $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$, $i\in[N]$, have no atoms, and satisfy
\begin{equation*}
\mathrm{conv}_g\,\mathrm{supp}(\mu^i_0)\cap\mathrm{conv}_g\,\mathrm{supp}(\mu_0^j)=\varnothing
\end{equation*}
for $i\neq j$. Fix $M\geqslant1$, and for any $i\in[N]$ consider
\begin{equation*}
    \mu^i_1:=\sum_{k=1}^M \alpha_k^i \updelta_{x_{k}^i}
\end{equation*}
where $x_k^i\in\mathrm{conv}_g\,\mathrm{supp}(\mu_0^i)$, with $x_k^i = x_{k'}^j$ if and only if $(k, i) = (k', j)$, and where $\alpha_k^i\geqslant 0$ with $\sum_{k=1}^M\alpha_k^i=1$. Then for any $T>0$ and $\varepsilon>0$ there exist piecewise constant $(\bm{\mathit{W}},\bm{\mathit{V}},b):[0,T]\to\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d)$ such that for $i\in[N]$, the corresponding unique solution $\mu^i\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ to (C.20) with data $\mu_0^i$ and these parameters satisfies
\begin{equation*}
\mathrm{conv}_g\,\mathrm{supp}\left(\mu^i(T)\right)\cap\mathrm{conv}_g\,\mathrm{supp}\left(\mu^j(T)\right)=\varnothing
\end{equation*}
for $i\neq j$, and 
\begin{equation*}
\mathsf{W}_2\left(\mu^i(T),\mu_1^{i}\right)\leqslant\varepsilon.
\end{equation*}

Suppose $d\geqslant3$. Consider 
\begin{equation*} \tag{$\mathscr{D}$}
  \left(x_0^i,y^i\right)\in\mathbb{S}^{d-1}\times\mathbb{S}^{d-1} \hspace{1cm} \text{ for } i\in[M], 
\end{equation*}
with $x_0^i\neq x_0^j$ and $y^i\neq y^j$ for $i\neq j$, and suppose that for any $i\in[M]$, there exist $\gamma_i\in\mathbb{S}^{d-1}$ and $\varepsilon_i>0$ such that
\begin{equation*} 
\left\langle\gamma_i,x_0^i-y^i\right\rangle=0 \hspace{1cm} \text{ and } \hspace{1cm} 
x_0^j\notin H_{\varepsilon_i}^{\gamma_i}
\end{equation*}
for $j\neq i\in[N]$, where
\begin{equation*}
H_{\varepsilon_i}^{\gamma_i}:=\Big\{x\in \mathbb{S}^{d-1}\colon|\langle x,\gamma_i\rangle|\leqslant \varepsilon_i\Big\}.
\end{equation*}
Then for any $T>0$, there exists $\theta=(\bm{\mathit{W}},\bm{\mathit{U}},b)\in L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R})^2\times\mathbb{R}^d)$, piecewise constant having at most $6M$ switches, such that for any $i\in[M]$, the solution $x^i(\cdot)\in \mathscr{C}^0([0,T];\mathbb{S}^{d-1})$ to
\begin{equation} 
\begin{cases}
\dot{x}^i(t)=\bm{\mathsf{P}}^\perp_x\left(\bm{\mathit{W}}(t)\Big(\bm{\mathit{U}}(t)x^i(t)+b(t)\Big)_+\right) &\text{ in } [0, T]\\
x^i(0)=x_0^i,
\end{cases}
\end{equation}
satisfies 
$$x^i(T)=y^i.$$
Moreover there exists some $C>0$, not depending on $\mathscr{D}$ nor $T$, such that
\begin{equation*}
\|\theta\|_{L^\infty((0,T);\Uptheta)}\leqslant \frac{C\cdot M}{\displaystyle T\min_{i\in[M]}\varepsilon_{i}}.
\end{equation*}

Let $T>0$. Suppose that $\mu_0^i\in\mathscr{P}(\mathbb{S}^{d-1})$, for $i\in[N]$, are such that 
\begin{equation*}
    \bigcup_{i\in[N]} \mathrm{supp}(\mu^i_0)\subset\mathbb{S}^{d-1}.
\end{equation*}
Then there exists $\theta=(\bm{\mathit{W}},\bm{\mathit{U}},\bm{\mathit{B}},\bm{\mathit{V}},b)\in L^\infty((0,T);\Uptheta)$ such that 
\begin{equation*}
\mathrm{supp}(\mu^i(T)) \subset \mathbb{Q}_1^{d-1}
\end{equation*}
for all $i\in[N]$ where $\mu^i\in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ denotes the unique solution to (1.4) corresponding to $\mu_0^i$ and $\theta$.

Furthermore, one can take $\bm{\mathit{V}}\equiv\bm{\mathit{B}}\equiv\bm{\mathit{U}}\equiv0$, $b\equiv{\bf 1}$, and $\bm{\mathit{W}}$ piecewise constant, having at most one switch, and satisfying
\begin{equation*}
\|\bm{\mathit{W}}\|_{L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R}))}\leqslant \frac{C}{T},
\end{equation*}
where $C>0$ depends only on the supports of the measures $\mu_0^i$, $i\in[N]$.

Let $T>0$ and let $\mu_0,\nu_0\in\mathscr{P}(\mathbb{Q}_1^{d-1})$ be two different measures such that
\begin{equation*}
        \mathbb{E}_{\mu_0}[x]= \gamma_1 \mathbb{E}_{\nu_0}[x]
    \end{equation*}
    for some $\gamma_1\in(0,1]$.
\begin{enumerate}
    \item If $\gamma_1=1$, then, setting $\bm{\mathit{V}}\equiv0$, there exist $\bm{\mathit{W}},\bm{\mathit{U}}\in\mathscr{M}_{d\times d}(\mathbb{R})$ and $b\in \mathbb{R}^d$ such that the unique solutions $\mu, \nu$ to (1.4)--(3.1) corresponding to $\mu_0, \nu_0$ and these parameters, satisfy
\begin{equation*}
    \mathbb{E}_{\mu(T)}[x]\neq \mathbb{E}_{\nu(T)}[x].
\end{equation*}
Moreover the Lipschitz-continuous and invertible flow map $\Phi^T:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics of (1.4)--(3.1) with these parameters satisfies
\begin{equation}
    \Phi^T(x)=x\hspace{1cm}\text{ for }x\in \mathbb{S}^{d-1}\setminus\left(\mathrm{supp}(\mu_0)\cup\mathrm{supp}(\nu_0)\right).
\end{equation}
\item If $\gamma\neq 1$, then, setting $\bm{\mathit{B}}\equiv0$, there exist $(\bm{\mathit{V}},\bm{\mathit{W}},\bm{\mathit{U}})\in L^\infty((0,T);\mathscr{M}_{d\times d}(\mathbb{R})^3)$ and $b\in L^\infty((0,T);\mathbb{R}^d)$,  piecewise constant with at most $2$ switches, such that the unique solutions $\mu, \nu$ to (1.4)--(3.1) corresponding to data $\mu_0, \nu_0$ and these parameters satisfy
\begin{equation*}
    \mathbb{E}_{\mu(T)}[x]\neq\gamma_2\mathbb{E}_{\nu(T)}[x]
\end{equation*}
for all $\gamma_2\in\mathbb{R}$. In fact, 
\begin{align*}
  \bm{\mathit{V}}(t)&=I_d 1_{(0,T_*)}(t) &  
  \bm{\mathit{W}}(t)&=\bm{\mathit{W}} 1_{(T_*,T)}(t) \\ 
  \bm{\mathit{U}}(t)&=\bm{\mathit{U}} 1_{(T_*,T)}(t) &
  b(t)&=b 1_{(T_*,T)}(t)  
\end{align*}
for some $T_*\in (0,T)$ and $\bm{\mathit{W}}, \bm{\mathit{U}}\in \mathscr{M}_{d\times d}(\mathbb{R})$, $b\in \mathbb{R}^d$. Moreover the Lipschitz-continuous and invertible flow map $\Phi^T:\mathbb{S}^{d-1}\to\mathbb{S}^{d-1}$ induced by the characteristics
\begin{equation*}
\begin{cases}
    \dot{x}(t)=\bm{\mathsf{P}}^\perp_x(\bm{\mathit{W}}(t)(\bm{\mathit{U}}(t) x+b(t))_+) &\text{ in } [0,T]\\
    x(0)=x\in\mathbb{S}^{d-1},
\end{cases}    
\end{equation*}
satisfies
\begin{equation*}
  \Phi^T(x)=x\hspace{1cm} \text{ for all }x\notin \mathrm{conv}_g\, \mathrm{supp}(\mu_0)\cup \mathrm{conv}_g\, \mathrm{supp}(\nu_0).
\end{equation*}
\end{enumerate}

Let $\mu_0^i\in\mathscr{P}(\mathbb{Q}_1^{d-1})$, $i\in[N]$, be given such that
    \begin{equation*}
        \mathbb{E}_{\mu_0^i}[x] \text{ is not colinear with }\mathbb{E}_{\mu_0^j}[x] \hspace{1cm} \text{ for } i\neq j.
    \end{equation*}
    Fix $j\in[N]$.
    Then for any $T>0$ and $\varepsilon>0$, and for any $\nu_0\in \mathscr{P}(\mathbb{Q}_1^{d-1})$ such that $\mathbb{E}_{\nu_0}[x]$ is colinear with $\mathbb{E}_{\mu_0^N}[x]$, there exists $\theta\in L^\infty((0,T);\Uptheta)$ such that 
    \begin{equation*}
        \mathrm{supp}(\nu(T))\cup\mathrm{supp}(\mu^j(T))\subset B\left( \frac{\mathbb{E}_{\mu^j_0}[z]}{\left\|\mathbb{E}_{\mu^j_0}[z]\right\|},\varepsilon\right),
    \end{equation*}
    and
    \begin{equation*}
        \mu^i(T)=\mu^i_0
    \end{equation*}
    for $i\neq j\in[N]$, where $\mu^i, \nu \in \mathscr{C}^0([0,T];\mathscr{P}(\mathbb{S}^{d-1}))$ 
    denote the unique solution to (1.4)--(3.1) corresponding to data $\mu_0^i$, $\nu_0$, and the parameters $\theta$.

Furthermore, one can take $\theta$ piecewise constant, having  $O(d\cdot N)$ switches.
